var tipuesearch = {"pages": [{'title': 'Final', 'text': '', 'tags': '', 'url': 'Final.html'}, {'title': 'h1', 'text': 'https://youtu.be/bCFZeYQadLI?si=O-Uyg9kUAveFMEJs \n', 'tags': '', 'url': 'h1.html'}, {'title': 'About', 'text': '>課程名稱: 計算機程式< \n github: https://github.com/0118ERIC/w123 \n ppt group4: https://0118eric.github.io/Group4ppt/ \n 影片: https://youtu.be/GyLxCKLxGR0 \n 課程評分: \n 學習心得報告 (60%)  - MS Teams 線上參與， 6人一組 每三週發表學習心得。 \n w3、w7、w10、w14、w17、w18 \n 學習心得報告主題: \n w3: 什麼是 git, GitHub, gist 與 cmsimde? 如何使用這些工具？為什麼要使用這些工具？ ( 動態模擬 ) \n w7: Brython 是什麼？如何在瀏覽器配置 Brython 環境？ Brython 能做什麼？ ( Brython ,  Examples ) \n w10: 如何在瀏覽器中模擬機器人作動？ ( 機器人作動 ) \n w14: 在瀏覽器中模擬機器人作動的目的是什麼？ ( otto_robot.7z ,\xa0 Plotter ,\xa0 open_duck_mini.7z  , https://webots.cloud/AcTNYs0 ) \n w17 ( 1b 採 Youtube 影片簡報 ): 計算機程式課程學到了什麼？ \n w18: 課程總結 \n 個人與分組網站維護 (40%)  - 每週至少兩次推送與課程進度相關的學習內容與心得。 \n w9 期中自評、w18 期末自評 \n', 'tags': '', 'url': 'About.html'}, {'title': '心得', 'text': '這幾堂課學會了許多，像是從靜端推上網路、活用AI、brython的一些寫發、cmd、網域設置等......許多將來也會用到的功能，對小弟我收穫良多，謝謝老師的教導和鼓勵。 \n 也讓我自己與ai寫了一款可以多人的貪食蛇，雖然伺服器是免費的，但與他人連線並遊玩已經是最大的進步了。 \n', 'tags': '', 'url': '心得.html'}, {'title': '貪食蛇 多人版', 'text': '我先用 github 當資料夾 並把 \n server.py 遊戲本體.html 用出來 並用免費伺服器 render 做成 \n https://github.com/0118ERIC/snake-sweet-for-u \n', 'tags': '', 'url': '貪食蛇 多人版.html'}, {'title': '鬼抓人遊戲 程式碼', 'text': 'from browser import document, html, timer import math, time \n # ===== 建立畫面 ===== document.clear() document <= html.H2("Brython 鬼抓人（30 秒生存版｜R 重新開始）") \n canvas = html.CANVAS(  width=500,  height=400,  style={  "border": "2px solid black",  "backgroundColor": "#222"  } ) document <= canvas \n ctx = canvas.getContext("2d") \n W, H = 500, 400 \n # ===== 障礙物 ===== obstacles = [  (150, 50, 200, 20),  (150, 330, 200, 20),  (240, 120, 20, 160) ] \n # ===== 遊戲狀態 ===== keys = set() win_time = 30 \n player = {} ghost = {} start_time = 0 game_over = False message = "" \n # ===== 初始化 / 重開 ===== def reset_game():  global player, ghost, start_time, game_over, message  player = {"x": 80, "y": 200, "r": 10, "speed": 4}  ghost = {"x": 420, "y": 200, "r": 12, "speed": 2}  start_time = time.time()  game_over = False  message = "" \n reset_game() \n # ===== 繪圖工具 ===== def draw_circle(x, y, r, color):  ctx.beginPath()  ctx.arc(x, y, r, 0, math.pi * 2)  ctx.fillStyle = color  ctx.fill() \n def draw_obstacles():  ctx.fillStyle = "#888"  for x, y, w, h in obstacles:  ctx.fillRect(x, y, w, h) \n # ===== 鍵盤 ===== def keydown(e):  keys.add(e.key)  if e.key.lower() == "r" and game_over:  reset_game() \n def keyup(e):  keys.discard(e.key) \n document.bind("keydown", keydown) document.bind("keyup", keyup) \n # ===== 玩家 ===== def update_player():  ox, oy = player["x"], player["y"] \n if "ArrowUp" in keys:  player["y"] -= player["speed"]  if "ArrowDown" in keys:  player["y"] += player["speed"]  if "ArrowLeft" in keys:  player["x"] -= player["speed"]  if "ArrowRight" in keys:  player["x"] += player["speed"] \n player["x"] = max(player["r"], min(W - player["r"], player["x"]))  player["y"] = max(player["r"], min(H - player["r"], player["y"])) \n for x, y, w, h in obstacles:  if x < player["x"] < x + w and y < player["y"] < y + h:  player["x"], player["y"] = ox, oy \n # ===== 鬼 ===== def update_ghost():  if ghost["x"] < player["x"]:  ghost["x"] += ghost["speed"]  if ghost["x"] > player["x"]:  ghost["x"] -= ghost["speed"]  if ghost["y"] < player["y"]:  ghost["y"] += ghost["speed"]  if ghost["y"] > player["y"]:  ghost["y"] -= ghost["speed"] \n # ===== 碰撞 ===== def hit():  dx = player["x"] - ghost["x"]  dy = player["y"] - ghost["y"]  return math.hypot(dx, dy) < player["r"] + ghost["r"] \n # ===== 主迴圈 ===== def game_loop():  global game_over, message \n ctx.clearRect(0, 0, W, H) \n elapsed = int(time.time() - start_time)  remain = max(0, win_time - elapsed) \n if not game_over:  update_player()  update_ghost() \n draw_obstacles()  draw_circle(player["x"], player["y"], player["r"], "#4af")  draw_circle(ghost["x"], ghost["y"], ghost["r"], "#f44") \n # 時間  ctx.fillStyle = "white"  ctx.font = "18px Arial"  ctx.fillText(f"剩餘時間：{remain}s", 10, 25) \n # 被抓到  if hit() and not game_over:  game_over = True  message = "嘿嘿抓到你摟 太陽出來瞜" \n # 勝利  if remain == 0 and not game_over:  game_over = True  message = "你撐到天亮了！" \n # 結束訊息（每一幀都畫 → 不會消失）  if message:  ctx.fillStyle = "yellow"  ctx.font = "22px Arial"  ctx.fillText(message, 40, 210)  ctx.font = "16px Arial"  ctx.fillText("按 R 重新開始", 170, 245) \n timer.request_animation_frame(lambda t: game_loop()) \n # ===== 啟動 ===== game_loop() \n', 'tags': '', 'url': '鬼抓人遊戲 程式碼.html'}, {'title': 'Brython', 'text': 'Brython  是一個將  Python  語法編譯為  JavaScript  的工具，能直接在瀏覽器中以  Python  撰寫前端網頁程式。 \n 1 add to 100 機器人巡邏 自由行 \n  導入 brython 程式庫  \n \n \n \n \n  啟動 Brython  \n \n \n \n  導入 FileSaver 與 filereader  \n \n \n \n \n  導入 ace  \n \n \n \n \n \n \n  導入 gearUtils-0.9.js Cango 齒輪繪圖程式庫  \n \n \n \n \n \n \n  請注意, 這裡使用 Javascript 將 localStorage["kw_py_src1"] 中存在近端瀏覽器的程式碼, 由使用者決定存檔名稱 \n \n \n \n  累加程式開始  \n \n  累加程式結束     機器人巡邏程式開始  \n \n  機器人巡邏程式結束  \n  機器人自由行程式開始  \n \n \n \n  機器人自由行程式結束  \n  add 1 to 100 開始  \n \n \n  add 1 to 100 結束 \n  editor1 開始  \n  用來顯示程式碼的 editor 區域  \n \n  以下的表單與按鈕與前面的 Javascript doSave 函式以及 FileSaver.min.js 互相配合  \n  存擋表單開始  \n Filename:  .py   \n  存擋表單結束  \n \n  執行與清除按鈕開始  \n Run   Output   清除輸出區 清除繪圖區 Reload \n  執行與清除按鈕結束  \n \n  程式執行 ouput 區  \n \n  Brython 程式執行的結果, 都以 brython_div1 作為切入位置  \n \n  editor1 結束   ##########################################  \n 從 1 累加到 100 part2: \n 1 add to 100 cango_three_gears BSnake AI Tetris \n  請注意, 這裡使用 Javascript 將 localStorage["kw_py_src2"] 中存在近端瀏覽器的程式碼, 由使用者決定存檔名稱 \n \n \n \n  add 1 to 100 part2 開始  \n \n \n  add 1 to 100 part2 結束 \n  editor2 開始  \n  用來顯示程式碼的 editor 區域  \n \n  以下的表單與按鈕與前面的 Javascript doSave 函式以及 FileSaver.min.js 互相配合  \n  存擋表單開始  \n Filename:  .py   \n  存擋表單結束  \n \n  執行與清除按鈕開始  \n Run   Output   清除輸出區 清除繪圖區 Reload \n  執行與清除按鈕結束  \n \n  程式執行 ouput 區  \n \n  Brython 程式執行的結果, 都以 brython_div1 作為切入位置  \n \n  editor2 結束  \n \n', 'tags': '', 'url': 'Brython.html'}, {'title': 'Pyodide3', 'text': 'Pyodide3 則在  Pyodide  與  Pyodide2  頁面架構下，進一步導入  robot_w_world.py ，在既有的水平圍牆  north.png  與垂直圍牆  east.png  檔案之外，加入  carrot.png 、 grass.png  與  pale_grass.png  等圖檔。並且擴充可從 URL 讀進 json 格式的 world 變數功能，以便製作出更多元的場景任務，要求機器人執行。 \n 其中 src URL 變數，可以將網路上的機器人控制程式導入 Pyodide3 頁面外，world URL 變數則可以導入源自  Reeborg  機器人程式所設定的 json 格式場景。 \n 由於 Reeborg 系統中的 png 圖檔均非透明背景， robot_w_world.py \xa0必須利用 HTML 中的 CANVAS，將關鍵的白色背景，以透明的方式顯示。 \n src URL 變數讀進  turn_right 程式 ，而 world URL 變數則讀進  harvest2.json ，執行 結果 。 \n 讀進  harvest3.json , 執行 結果 。 \n \n \n \n version   hello   1 add to 100   機器人巡邏   自由行   numpy_ode \n  Ace Editor Scripts  \n \n \n \n \n \n \n \n \n  Editor 1  \n \n Run   Output   清除輸出區   Reload \n \n \n \n \n \n 從 1 累加到 100 part2: \n 1 add to 100 \n  Editor 2  \n \n Run   Output   清除輸出區   Reload \n \n \n \n \n \n \n', 'tags': '', 'url': 'Pyodide3.html'}]};